-- French and English texts for the menorahs already imported from Art Judaica
-- (db/import-art-hanukkah.sql). Only updates the texts of menorahs that are
-- still on the site: deleted ones are NOT brought back, and prices, visibility
-- and photos are left as they are. Safe to run more than once.

update public.products as p
set name_fr = v.name_fr,
    name_en = v.name_en,
    subtitle_he = v.subtitle_he,
    subtitle_fr = v.subtitle_fr,
    subtitle_en = v.subtitle_en,
